    o.background=hex.test(options.background||'')?options.background:DEFAULTS.background;
    for(const [key,min,max] of [['angle',0,360],['speed',.25,3],['intensity',0,1],['duration',.5,8],['hold',0,12],['glow',0,12],['fontSize',6,32],['lineHeight',.8,1.8]])o[key]=number(options[key],DEFAULTS[key],min,max);
