function mountASCII(host, overrides={}){ return ASCIIStudio.create(host,art,{...settings,recordings,...overrides}); }


(function spot64ArtworkBridge() {
  'use strict';
  let player = null;
  let host = null;
  let container = null;
  let previousMode = false;

  function syncArtwork() {
    const root = document.getElementById('tm-root');
    if (!root) return;
    const active = root.classList.contains('tm-art-mode');
    const artwork = root.querySelector('.tm-artwork');
    if (!artwork) return;
    if (!active) {
      if (player) { player.pause(); }
      previousMode = false;
      return;
    }
    if (!player) {
      const placeholder = artwork.querySelector('.tm-artwork-text');
      if (placeholder) placeholder.style.display = 'none';
      container = document.createElement('div');
      container.className = 'tm-original-ascii-host';
      container.style.cssText = 'width:100%;height:auto;min-width:0;display:flex;align-items:center;justify-content:center;overflow:hidden;';
      artwork.append(container);
      try {
        player = mountASCII(container, { transparentPreview: true });
        host = artwork;
      } catch (error) {
        console.error('[Spot64 artwork] Could not mount original animation:', error);
        container.remove(); container = null;
        if (placeholder) placeholder.style.display = '';
        return;
      }
    }
    if (player && !previousMode) player.play();
    previousMode = true;
  }

  const style = document.createElement('style');
  style.textContent = `
    #tm-root.tm-art-mode .tm-artwork-text { display: none !important; }
    #tm-root.tm-art-mode .tm-artwork { background: #0b0e12 !important; }
    #tm-root.tm-art-mode .tm-original-ascii-host { max-width: 100%; }
    #tm-root.tm-art-mode .tm-original-ascii-host canvas { max-width: 100%; }
  `;
  document.head.append(style);

  const interval = setInterval(() => {
    const root = document.getElementById('tm-root');
    if (!root || !root.querySelector('.tm-art-toggle')) return;
    clearInterval(interval);
    const observer = new MutationObserver(() => syncArtwork());
    observer.observe(root, { attributes: true, attributeFilter: ['class'] });
    syncArtwork();
  }, 250);
})();
